from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from knox.models import AuthToken

class DeviceTokenRevokeView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def delete(self, request, token_prefix):
        # Ensure the token belongs to the authenticated user before deletion
        tokens = AuthToken.objects.filter(user=request.user, token_key=token_prefix)
        if not tokens.exists():
            return Response({"error": "Session token not found"}, status=status.HTTP_404_NOT_FOUND)

        tokens.delete()
        return Response({"status": "Session revoked successfully"}, status=status.HTTP_200_OK)
